{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Paliperidone, which shares the 5-fluorobenzisoxazole-piperidine core with the query, has an absolute oral bioavailability of 28% in healthy fasting volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Risperidone, a close structural analogue containing the same benzisoxazole-piperidine moiety, has an absolute oral bioavailability of 66% in healthy men.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "9-Hydroxyrisperidone, the active metabolite sharing the same core, is reported to have complete oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Melperone, a piperidine/fluorophenyl antipsychotic, has an absolute oral bioavailability of 54 ± 24.2% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Lumateperone, a more distantly related piperidine/fluorophenyl antipsychotic, has an absolute oral bioavailability of about 4.4%, providing low-bioavailability evidence, but its much lower structural similarity limits transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have high absolute oral bioavailability (F >= 20%) because its closest structural analogues—paliperidone, risperidone, and 9-hydroxyrisperidone—all show absolute oral bioavailability above 20% (28%, 66%, and complete, respectively). Additional piperidine/fluorophenyl antipsychotics such as melperone also support high F. The low-F example lumateperone is too structurally distant to override this consistent pattern.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the exact query molecule was retrieved; the prediction relies on close structural analogues.",
    "The query's unique propoxy-acetophenone side chain may alter metabolic clearance and absorption compared with the closest analogues.",
    "Lumateperone demonstrates that low bioavailability is possible in this chemical space, but its rigid polycyclic scaffold limits direct extrapolation to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

